import{_ as e,o as d,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"LangChain.js API 索引","description":"按包与 API 家族速查本手册 Agent 篇实际讲过的 LangChain.js 入口、签名直觉与正文链接。","frontmatter":{"title":"LangChain.js API 索引","description":"按包与 API 家族速查本手册 Agent 篇实际讲过的 LangChain.js 入口、签名直觉与正文链接。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/api-index/langchain-api-index.md","filePath":"ts-ai/appendix/api-index/langchain-api-index.md","lastUpdated":1786166505000}'),c={name:"ts-ai/appendix/api-index/langchain-api-index.md"};function r(n,t,s,i,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="langchain-js-api-索引" tabindex="-1">LangChain.js API 索引 <a class="header-anchor" href="#langchain-js-api-索引" aria-label="Permalink to &quot;LangChain.js API 索引&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本索引帮助你从类名/方法名跳回正文，而不是重复教程。条目只收录 <code>docs/ts-ai/agent</code> 中已展开的 API；签名以各正文篇与当前包类型定义为准。</p><h2 id="_1-索引范围与排除" tabindex="-1">1. 索引范围与排除 <a class="header-anchor" href="#_1-索引范围与排除" aria-label="Permalink to &quot;1. 索引范围与排除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包含</th><th>排除</th></tr></thead><tbody><tr><td><code>@langchain/core</code>、<code>langchain</code>、<code>@langchain/openai</code>、<code>@langchain/mcp-adapters</code> 中本手册讲过的入口</td><td>未在正文出现的冷门导出、Python 包名、完整示例教程</td></tr><tr><td>ChatModel、Message/Prompt、Runnable、Tool、结构化输出、<code>createAgent</code> / Middleware</td><td>LangGraph <code>StateGraph</code> / Checkpoint / <code>interrupt</code>（见 <a href="/ts-ai/appendix/api-index/langgraph-api-index">LangGraph.js API 索引</a>）</td></tr><tr><td>调用侧 config、常见事件名与错误归类</td><td>NestJS/SSE 协议细节、模型供应商原生 SDK 百科</td></tr></tbody></table><p>查 API 时：先看本节「包与入口」，再进对应 API 家族；需要机制与边界时跟随链接进正文。</p><h2 id="_2-包与入口对象" tabindex="-1">2. 包与入口对象 <a class="header-anchor" href="#_2-包与入口对象" aria-label="Permalink to &quot;2. 包与入口对象&quot;">​</a></h2><h3 id="_2-1-langchain-core-langchain-供应商包" tabindex="-1">2.1 <code>@langchain/core</code> / <code>langchain</code> / 供应商包 <a class="header-anchor" href="#_2-1-langchain-core-langchain-供应商包" aria-label="Permalink to &quot;2.1 `@langchain/core` / `langchain` / 供应商包&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>本手册常用入口</th><th>正文</th></tr></thead><tbody><tr><td><code>@langchain/core/messages</code></td><td><code>HumanMessage</code>、<code>AIMessage</code>、<code>SystemMessage</code>、<code>ToolMessage</code>、<code>trimMessages</code></td><td><a href="/ts-ai/agent/langchain-core/messages-prompt-template">Message 与 Prompt 家族</a></td></tr><tr><td><code>@langchain/core/prompts</code></td><td><code>PromptTemplate</code>、<code>ChatPromptTemplate</code>、<code>MessagesPlaceholder</code></td><td>同上</td></tr><tr><td><code>@langchain/core/runnables</code></td><td><code>Runnable</code>、<code>RunnableSequence</code>、<code>RunnableLambda</code>、<code>RunnableBranch</code> 等</td><td><a href="/ts-ai/agent/langchain-core/runnable-invoke-batch-stream">Runnable：invoke、batch 与 stream</a>、<a href="/ts-ai/agent/langchain-core/runnable-composition-events">Runnable 组合、容错与事件</a></td></tr><tr><td><code>@langchain/core/output_parsers</code></td><td><code>StringOutputParser</code>、<code>JsonOutputParser</code> 等</td><td><a href="/ts-ai/agent/models-output/output-parsers">Output Parsers</a></td></tr><tr><td><code>langchain</code></td><td><code>createAgent</code>、<code>tool</code>、<code>createMiddleware</code></td><td><a href="/ts-ai/agent/runtime/create-agent">createAgent</a>、<a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a>、<a href="/ts-ai/agent/runtime/middleware-guardrails">Middleware</a></td></tr><tr><td><code>@langchain/openai</code></td><td><code>ChatOpenAI</code>、<code>OpenAIEmbeddings</code>（点名）</td><td><a href="/ts-ai/agent/langchain-core/chat-model-chatopenai">ChatModel 与 ChatOpenAI</a>、<a href="/ts-ai/agent/langchain-core/ecosystem-packages-versioning">生态包与版本对齐</a></td></tr><tr><td><code>@langchain/mcp-adapters</code></td><td><code>MultiServerMCPClient</code>、<code>loadMcpTools</code></td><td><a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a></td></tr></tbody></table><p>安装与版本对齐规则见<a href="/ts-ai/agent/langchain-core/ecosystem-packages-versioning">生态包与版本对齐</a>。本手册默认模型实现是 <code>@langchain/openai</code> 的 <code>ChatOpenAI</code>。</p><h2 id="_3-核心-api-家族" tabindex="-1">3. 核心 API 家族 <a class="header-anchor" href="#_3-核心-api-家族" aria-label="Permalink to &quot;3. 核心 API 家族&quot;">​</a></h2><h3 id="_3-1-chatmodel-chatopenai" tabindex="-1">3.1 <code>ChatModel</code> / <code>ChatOpenAI</code> <a class="header-anchor" href="#_3-1-chatmodel-chatopenai" aria-label="Permalink to &quot;3.1 `ChatModel` / `ChatOpenAI`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>ChatOpenAI</code> / <code>BaseChatModel</code></td><td>统一聊天模型：输入消息，输出 <code>AIMessage</code>（流式为 chunk）</td><td><code>new ChatOpenAI({ model, temperature?, maxTokens?, timeout?, maxRetries?, configuration? })</code></td><td><a href="/ts-ai/agent/langchain-core/chat-model-chatopenai">ChatModel 与 ChatOpenAI</a></td></tr><tr><td><code>model.invoke</code></td><td>完成一次生成</td><td><code>invoke(messages | string | PromptValue, config?) → AIMessage</code></td><td>同上；调用语义见 <a href="/ts-ai/agent/langchain-core/runnable-invoke-batch-stream">Runnable 调用</a></td></tr><tr><td><code>bindTools</code></td><td>把工具契约挂到模型，<strong>不执行</strong>工具</td><td><code>bindTools(tools) → Runnable</code>；输出可含 <code>tool_calls</code></td><td><a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a></td></tr><tr><td><code>withStructuredOutput</code></td><td>按 Zod/JSON Schema 约束结构化返回</td><td><code>withStructuredOutput(schema, { method?, strict?, includeRaw? }) → Runnable</code></td><td><a href="/ts-ai/agent/models-output/zod-structured-output">Zod 结构化输出</a></td></tr><tr><td><code>withConfig</code></td><td>绑定 <code>runName</code> / tags / metadata，不改原实例</td><td><code>withConfig({ runName?, tags?, metadata?, stop? })</code></td><td><a href="/ts-ai/agent/langchain-core/chat-model-chatopenai">ChatModel</a>、<a href="/ts-ai/agent/models-output/model-parameters-configuration">模型参数</a></td></tr><tr><td><code>withFallbacks</code> / <code>withRetry</code></td><td>跨模型降级 / 可重试错误重试</td><td><code>withFallbacks({ fallbacks: [otherModel] })</code>；fallback 须不同模型或供应商</td><td><a href="/ts-ai/agent/models-output/model-routing-fallbacks">模型路由与回退</a></td></tr><tr><td><code>FakeListChatModel</code></td><td>（遗留）固定回复序列；新文优先 <code>fakeModel()</code></td><td>构造时提供预设响应列表</td><td><a href="/ts-ai/agent/langchain-core/chat-model-chatopenai">ChatModel</a>（主路见 Fake 测试）</td></tr><tr><td><code>fakeModel</code></td><td>手册测试主路：排队文本 / tool_calls / 结构化返回 / 抛错</td><td><code>fakeModel().respond(...)</code> / <code>.structuredResponse(...)</code></td><td><a href="/ts-ai/foundations/langchain-bridge/model-call-tests">模型调用的 Fake、Mock 与错误测试</a></td></tr></tbody></table><p>关注输出字段：<code>AIMessage.content</code>、<code>tool_calls</code>、<code>usage_metadata</code>、<code>response_metadata</code>；流式为 <code>AIMessageChunk</code> / <code>tool_call_chunks</code>。</p><h3 id="_3-2-message-与-prompt" tabindex="-1">3.2 Message 与 Prompt <a class="header-anchor" href="#_3-2-message-与-prompt" aria-label="Permalink to &quot;3.2 Message 与 Prompt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>BaseMessage</code></td><td>消息基类；共用 <code>content</code> / <code>id</code> / <code>name</code> 等</td><td>优先用专用子类，少用裸字符串拼历史</td><td><a href="/ts-ai/agent/langchain-core/messages-prompt-template">Message 与 Prompt 家族</a></td></tr><tr><td><code>SystemMessage</code> / <code>HumanMessage</code> / <code>AIMessage</code></td><td>系统策略、用户输入、助手输出</td><td><code>new HumanMessage(&quot;…&quot;)</code>；<code>AIMessage</code> 可带 <code>tool_calls</code></td><td>同上</td></tr><tr><td><code>ToolMessage</code></td><td>把工具结果回灌给模型</td><td><code>new ToolMessage({ content, tool_call_id })</code>；<code>tool_call_id</code> 必对齐</td><td><a href="/ts-ai/agent/tools-mcp/tool-call-tool-message">Tool Call 与 ToolMessage</a></td></tr><tr><td><code>RemoveMessage</code></td><td>在可编辑消息状态中标记删除</td><td>与图/Agent 的 messages reducer 配合</td><td><a href="/ts-ai/agent/langchain-core/messages-prompt-template">Message 与 Prompt 家族</a></td></tr><tr><td><code>filterMessages</code> / <code>trimMessages</code></td><td>过滤或按 token 预算裁剪消息列表</td><td><code>trimMessages(messages, { maxTokens, strategy, startOn? })</code></td><td><a href="/ts-ai/agent/langchain-core/messages-prompt-template">Message 与 Prompt</a>、<a href="/ts-ai/agent/models-output/context-budget-trimming">上下文预算</a></td></tr><tr><td><code>PromptTemplate</code></td><td>单字符串模板 → 字符串</td><td><code>fromTemplate(&quot;…{var}…&quot;)</code>；<code>format</code> / <code>invoke</code> / <code>partial</code></td><td><a href="/ts-ai/agent/langchain-core/messages-prompt-template">Message 与 Prompt 家族</a></td></tr><tr><td><code>ChatPromptTemplate</code></td><td>聊天消息模板主路径</td><td><code>fromMessages([[&quot;system&quot;,&quot;…&quot;], [&quot;human&quot;,&quot;…&quot;]])</code>；<code>formatMessages</code> / <code>invoke</code></td><td>同上</td></tr><tr><td><code>MessagesPlaceholder</code></td><td>在模板中插入历史 <code>BaseMessage[]</code></td><td><code>new MessagesPlaceholder(&quot;history&quot;)</code></td><td>同上</td></tr><tr><td><code>FewShotPromptTemplate</code> / <code>FewShotChatMessagePromptTemplate</code></td><td>少样本字符串 / 聊天示例</td><td>示例集需版本管理</td><td>同上</td></tr><tr><td><code>PipelinePromptTemplate</code></td><td>多段提示组合</td><td>把子模板流水线拼成最终提示</td><td>同上</td></tr></tbody></table><h3 id="_3-3-runnable-invoke-batch-stream" tabindex="-1">3.3 Runnable：<code>invoke</code> / <code>batch</code> / <code>stream</code> <a class="header-anchor" href="#_3-3-runnable-invoke-batch-stream" aria-label="Permalink to &quot;3.3 Runnable：`invoke` / `batch` / `stream`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>invoke</code></td><td>一次输入 → 一次完整输出</td><td><code>runnable.invoke(input, config?)</code></td><td><a href="/ts-ai/agent/langchain-core/runnable-invoke-batch-stream">Runnable：invoke、batch 与 stream</a></td></tr><tr><td><code>batch</code></td><td>多输入批量；可控并发</td><td><code>batch(inputs, { maxConcurrency? })</code>；在线多用户勿塞进一次 batch</td><td>同上</td></tr><tr><td><code>stream</code></td><td>增量产出（token 或中间块，视实现）</td><td><code>for await (const chunk of runnable.stream(input, config?))</code></td><td>同上；Agent 语义见 <a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式取消恢复</a></td></tr><tr><td><code>pipe</code> / <code>RunnableSequence</code></td><td>顺序组合 Prompt → Model → Parser</td><td><code>prompt.pipe(model).pipe(parser)</code> 或 <code>RunnableSequence.from([...])</code></td><td><a href="/ts-ai/agent/langchain-core/runnable-composition-events">Runnable 组合、容错与事件</a></td></tr><tr><td><code>RunnableLambda</code></td><td>把函数包成 Runnable</td><td><code>RunnableLambda.from(async (input) =&gt; …)</code></td><td>同上</td></tr><tr><td><code>RunnablePassthrough</code> / <code>RunnableAssign</code> / <code>RunnablePick</code></td><td>透传、追加键、挑选字段</td><td>常与对象字面量并行字典一起用</td><td>同上</td></tr><tr><td><code>RunnableMap</code> / <code>RunnableParallel</code></td><td>并行多路，合并为对象</td><td>并行字典或显式 Parallel</td><td>同上</td></tr><tr><td><code>RunnableBranch</code> / <code>RouterRunnable</code></td><td>有限分支 / 路由表选择子链</td><td>Branch：条件数组 + 默认链；开放工具选择用 Agent</td><td>同上</td></tr><tr><td><code>RunnableEach</code></td><td>对数组逐元素应用同一 Runnable</td><td>注意总调用次数与限流</td><td>同上</td></tr><tr><td><code>RunnableWithMessageHistory</code></td><td>为链包装会话历史读写</td><td>提供 <code>getMessageHistory</code>；调用侧传 session 配置</td><td>同上；存储策略见记忆篇</td></tr><tr><td><code>withConfig</code>（Runnable）</td><td>固定 tags / metadata / runName</td><td>与单次调用第二参 config 合并</td><td><a href="/ts-ai/agent/langchain-core/runnable-invoke-batch-stream">Runnable 调用</a></td></tr><tr><td><code>streamEvents</code></td><td>暴露链内阶段事件（v2 协议为主）</td><td><code>streamEvents(input, { version: &quot;v2&quot;, … })</code></td><td><a href="/ts-ai/agent/langchain-core/runnable-composition-events">Runnable 组合、容错与事件</a></td></tr></tbody></table><p><code>RunnableConfig</code> 常用字段：<code>tags</code>、<code>metadata</code>、<code>runName</code>、<code>signal</code>（<code>AbortSignal</code>）、<code>callbacks</code>、<code>maxConcurrency</code>。</p><h3 id="_3-4-tool-与结构化输出" tabindex="-1">3.4 Tool 与结构化输出 <a class="header-anchor" href="#_3-4-tool-与结构化输出" aria-label="Permalink to &quot;3.4 Tool 与结构化输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>tool</code></td><td>用名称、描述、Zod schema 与实现定义工具</td><td><code>tool(fn, { name, description, schema })</code>；也可 <code>tool.invoke</code> 单测</td><td><a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a></td></tr><tr><td><code>AIMessage.tool_calls</code></td><td>模型提出的动作请求列表</td><td>每项含 <code>id</code> / <code>name</code> / <code>args</code>；并行时多项</td><td><a href="/ts-ai/agent/tools-mcp/tool-call-tool-message">Tool Call 与 ToolMessage</a></td></tr><tr><td><code>ToolMessage</code> + <code>tool_call_id</code></td><td>执行结果回灌；无匹配则循环断裂</td><td>每个 <code>tool_call_id</code> 恰好一条回灌（除非 Middleware 刻意合并）</td><td>同上</td></tr><tr><td><code>StringOutputParser</code> / <code>JsonOutputParser</code></td><td>从 <code>AIMessage</code> 抽文本 / 解析 JSON</td><td>放在 <code>model</code> 之后；JSON 路径仍建议再 Zod 校验</td><td><a href="/ts-ai/agent/models-output/output-parsers">Output Parsers</a></td></tr><tr><td><code>JsonOutputToolsParser</code> / <code>JsonOutputKeyToolsParser</code></td><td>从 tool calling 路径解析参数</td><td>保证力度通常弱于 <code>withStructuredOutput</code></td><td>同上</td></tr><tr><td><code>withStructuredOutput</code></td><td>固定契约优先路径</td><td>见 §3.1；<code>method</code> / <code>strict</code> / <code>includeRaw</code> 影响行为</td><td><a href="/ts-ai/agent/models-output/zod-structured-output">Zod 结构化输出</a></td></tr><tr><td><code>MultiServerMCPClient</code></td><td>发现多 MCP Server 工具并转为 LangChain 工具</td><td><code>new MultiServerMCPClient(servers)</code> → <code>getTools()</code></td><td><a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a></td></tr><tr><td><code>loadMcpTools</code></td><td>已有 MCP <code>Client</code> 时加载工具</td><td><code>loadMcpTools(serverName, client)</code></td><td>同上</td></tr><tr><td><code>ToolException</code></td><td>MCP/<code>isError</code> 等失败在 TS 适配器侧抛出</td><td>Middleware 捕获；不像 Python 自动变失败 <code>ToolMessage</code></td><td>同上；错误语义见 <a href="/ts-ai/agent/tools-mcp/tool-errors-timeouts-results">工具错误</a></td></tr></tbody></table><p>可信字段（<code>userId</code> / <code>tenantId</code>）走 <code>context</code> / <code>contextSchema</code>，不要让模型填写；见 <a href="/ts-ai/agent/tools-mcp/runtime-context-injection">Runtime Context 可信注入</a>。</p><h3 id="_3-5-createagent-与-runtime" tabindex="-1">3.5 <code>createAgent</code> 与 Runtime <a class="header-anchor" href="#_3-5-createagent-与-runtime" aria-label="Permalink to &quot;3.5 `createAgent` 与 Runtime&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>createAgent</code></td><td>组装 Model + Harness（默认 ReAct 工具循环）</td><td><code>createAgent({ model, tools, systemPrompt, middleware?, contextSchema?, checkpointer?, responseFormat? })</code> → <code>ReactAgent</code></td><td><a href="/ts-ai/agent/runtime/create-agent">使用 createAgent 创建 Agent</a></td></tr><tr><td><code>agent.invoke</code></td><td>跑完整 Agent Run，返回终态（含完整 <code>messages</code>）</td><td><code>invoke({ messages }, { configurable?, context?, signal? })</code></td><td>同上；State/Context 见 <a href="/ts-ai/agent/runtime/state-context-lifecycle">生命周期</a></td></tr><tr><td><code>agent.stream</code> / <code>agent.streamEvents</code></td><td>暴露中间 State 块或 Harness 阶段事件</td><td>Agent <code>stream</code> 常为状态更新，非纯 token 流；事件示例可用 <code>version: &quot;v3&quot;</code></td><td><a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式、取消与恢复</a></td></tr><tr><td><code>createMiddleware</code></td><td>在固定钩子注入策略，不改写 Harness 内核</td><td><code>createMiddleware({ name, beforeModel?, wrapModelCall?, wrapToolCall?, … })</code></td><td><a href="/ts-ai/agent/runtime/middleware-guardrails">Middleware 与 Guardrails</a></td></tr><tr><td>Node 钩子 <code>beforeAgent</code> / <code>beforeModel</code> / <code>afterModel</code> / <code>afterAgent</code></td><td>在图节点边界改 State 或汇总</td><td>返回部分 State 更新；顺序影响行为</td><td>同上</td></tr><tr><td>Wrap 钩子 <code>wrapModelCall</code> / <code>wrapToolCall</code></td><td>包裹单次模型/工具调用，可校验、超时、redact</td><td><code>(request, handler) =&gt; handler(request)</code>；应传递 <code>signal</code></td><td>同上；Context 工程见 <a href="/ts-ai/agent/runtime/context-engineering">上下文工程</a></td></tr><tr><td><code>context</code> / <code>contextSchema</code></td><td>单次 invoke 受信配置，不默认进 prompt</td><td>创建时声明 Schema；调用时第二参传入</td><td><a href="/ts-ai/agent/runtime/state-context-lifecycle">State、Context 与生命周期</a>、<a href="/ts-ai/agent/tools-mcp/runtime-context-injection">Runtime Context</a></td></tr><tr><td><code>stateSchema</code> / <code>responseFormat</code></td><td>扩展 Agent State；约束最终结构化输出</td><td>入门可只操作 <code>messages</code>；结构见 Zod 篇</td><td><a href="/ts-ai/agent/runtime/create-agent">createAgent</a>、<a href="/ts-ai/agent/models-output/zod-structured-output">Zod 结构化输出</a></td></tr></tbody></table><p>选型边界（Chain / Agent / Workflow）见 <a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a>。手写图、Interrupt、Checkpoint 属 LangGraph 索引。</p><h2 id="_4-事件、错误与配置速查" tabindex="-1">4. 事件、错误与配置速查 <a class="header-anchor" href="#_4-事件、错误与配置速查" aria-label="Permalink to &quot;4. 事件、错误与配置速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>关键项</th><th>放哪里处理</th><th>正文</th></tr></thead><tbody><tr><td>LCEL 事件</td><td><code>on_chain_*</code>、<code>on_chat_model_*</code>、<code>on_parser_*</code>、<code>on_tool_*</code></td><td><code>streamEvents</code>（链：<code>version: &quot;v2&quot;</code>）</td><td><a href="/ts-ai/agent/langchain-core/runnable-composition-events">Runnable 组合、容错与事件</a></td></tr><tr><td>Agent 进度</td><td>State 块 / Harness snapshot</td><td><code>agent.stream</code> 或 <code>agent.streamEvents</code></td><td><a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式、取消与恢复</a></td></tr><tr><td>取消</td><td><code>AbortSignal</code> / <code>config.signal</code></td><td>调用第二参；Middleware 须向下传递</td><td>同上；Runnable config 见 <a href="/ts-ai/agent/langchain-core/runnable-invoke-batch-stream">invoke 篇</a></td></tr><tr><td>观测标注</td><td><code>runName</code>、<code>tags</code>、<code>metadata</code></td><td><code>withConfig</code> 或单次 config；勿把密钥打进日志</td><td><a href="/ts-ai/agent/models-output/model-parameters-configuration">模型参数</a></td></tr><tr><td>输入错误</td><td>模板变量缺失、Zod 工具参数非法</td><td>进模型/执行工具前失败</td><td><a href="/ts-ai/agent/langchain-core/messages-prompt-template">Prompt</a>、<a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool</a></td></tr><tr><td>传输/供应商错误</td><td>超时、401、429、5xx、内容过滤</td><td>区分 <code>maxRetries</code> / <code>withRetry</code> / 队列重试，避免三层叠加</td><td><a href="/ts-ai/agent/langchain-core/runnable-invoke-batch-stream">Runnable 调用</a>、<a href="/ts-ai/agent/models-output/model-routing-fallbacks">模型路由</a></td></tr><tr><td>输出错误</td><td>Parser 失败、字段缺失</td><td>升级 <code>withStructuredOutput</code> + 本地业务校验</td><td><a href="/ts-ai/agent/models-output/output-parsers">Output Parsers</a>、<a href="/ts-ai/agent/models-output/zod-structured-output">Zod</a></td></tr><tr><td>工具/MCP</td><td><code>ToolException</code>、超时、需脱敏结果</td><td><code>wrapToolCall</code> 或工具实现内处理</td><td><a href="/ts-ai/agent/tools-mcp/tool-errors-timeouts-results">工具错误</a>、<a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">MCP 集成</a></td></tr><tr><td>Guardrails</td><td>步数上限、PII、工具权限</td><td>Middleware 钩子，而非改 Prompt 劝阻</td><td><a href="/ts-ai/agent/runtime/middleware-guardrails">Middleware 与 Guardrails</a></td></tr></tbody></table><p>遗留：<code>streamLog</code> 仅收录为对照；新代码主路径用 <code>stream</code> / <code>streamEvents</code>。</p><h2 id="_5-关联章节" tabindex="-1">5. 关联章节 <a class="header-anchor" href="#_5-关联章节" aria-label="Permalink to &quot;5. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>用本索引时怎么用</th></tr></thead><tbody><tr><td><a href="/ts-ai/agent/">Agent 总览</a></td><td>建立 Model → Tools → Runtime 学习顺序</td></tr><tr><td><a href="/ts-ai/agent/langchain-core/">LangChain Core</a></td><td>ChatModel、Message/Prompt、Runnable 主文</td></tr><tr><td><a href="/ts-ai/agent/models-output/">模型与输出</a></td><td>参数、Parser、结构化输出、裁剪与回退</td></tr><tr><td><a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a></td><td><code>tool</code>、Tool Call、Context、MCP 适配</td></tr><tr><td><a href="/ts-ai/agent/runtime/">Agent Runtime</a></td><td><code>createAgent</code>、Middleware、流式与边界</td></tr><tr><td><a href="/ts-ai/agent/assembly/assembly-recipes-checklist">Agent 组装清单</a></td><td>按配方验收「会用哪些 API」</td></tr><tr><td><a href="/ts-ai/appendix/api-index/langgraph-api-index">LangGraph.js API 索引</a></td><td>图、Checkpoint、Interrupt、多 Agent 入口</td></tr><tr><td><a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a></td><td>行为验收勾选，不代替本索引的 API 跳转</td></tr><tr><td><a href="/ts-ai/appendix/references/official-resources">官方资料索引</a></td><td>本索引未收录的 API，以官方文档为准</td></tr></tbody></table>',30)])])}const m=e(c,[["render",r]]);export{u as __pageData,m as default};
